node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Look up order ORD-E0E671
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get('ORD-E0E671');
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Look up order items
const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all('ORD-E0E671');
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Look up the specific item
const variant = db.prepare('SELECT * FROM rt_variants WHERE item_id = ?').get('ITEM-E5801A');
console.log('\n=== VARIANT ITEM-E5801A ===');
console.log(JSON.stringify(variant, null, 2));

// Look up the product for that variant
if (variant) {
  const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(variant.product_id);
  console.log('\n=== PRODUCT (Aurora Smart Desk Lamp Pro) ===');
  console.log(JSON.stringify(product, null, 2));
}
"

